// Package chainledger implements the on-chain data governance core.
package chainledger

import (
	"errors"
	"fmt"
	"sort"
)

// Sentinel errors so callers can recognize rejection reasons with errors.Is.
var (
	// ErrInvalidArgument is returned for malformed requests (empty names,
	// nil lineage nodes referenced as upstreams).
	ErrInvalidArgument = errors.New("invalid argument")
	// ErrNotFound is returned when an upstream dataset is not registered.
	ErrNotFound = errors.New("not found")
	// ErrCycle is returned when applying the registration would form a cycle.
	ErrCycle = errors.New("cycle detected")
	// ErrNotInitialized is returned when the graph map itself is nil.
	ErrNotInitialized = errors.New("lineage graph is not initialized")
)

// Dataset is one ingestible on-chain data source with a declared schema version.
type Dataset struct {
	Name          string
	SchemaVersion int
	Rows          int
	Upstreams     []string
}

// Lineage records where a dataset came from, so every derived table can be traced.
// Parents and Children are always sorted by name and free of duplicates.
type Lineage struct {
	Dataset  string
	Parents  []string
	Children []string
}

// Register links a dataset into the lineage graph.
//
// Registering an existing dataset name REPLACES its direct upstream (parent)
// relationships with the given parents:
//   - downstream (child) relationships of the dataset are preserved;
//   - parents dropped from the list no longer list the dataset as a child;
//   - newly added parents list the dataset exactly once;
//   - a nil or empty parents slice removes every direct upstream, turning the
//     dataset into a root while keeping its downstream.
//
// Duplicate parent names count as one relationship, and the stored lineage is
// independent of the caller's slice: mutating parents after Register returns
// does not affect the graph.
//
// Registration is atomic. If any parent is missing or the resulting graph
// would contain a cycle (including a dataset depending on itself, directly or
// through other nodes), no node and no parent/child record is changed. Cycle
// validation uses the relationships as they will be AFTER the replacement, so
// an edge removed by this registration cannot make a legal change fail.
func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
	if graph == nil {
		return fmt.Errorf("%w: create the graph map with make before registering datasets", ErrNotInitialized)
	}
	if dataset.Name == "" {
		return fmt.Errorf("%w: dataset name is required", ErrInvalidArgument)
	}

	// Normalize on a copy: dedupe (duplicates are one relationship), sort,
	// and detach from the caller's backing array.
	wanted := uniqueSorted(parents)
	for _, parent := range wanted {
		entry, ok := graph[parent]
		if !ok {
			return fmt.Errorf("%w: upstream dataset %q is not registered", ErrNotFound, parent)
		}
		if entry == nil {
			return fmt.Errorf("%w: upstream dataset %q points to a nil lineage node", ErrInvalidArgument, parent)
		}
	}

	// Snapshot the current parents so validation can reason about the graph
	// after the replacement, before anything is mutated.
	var oldParents []string
	if current := graph[dataset.Name]; current != nil {
		oldParents = append(oldParents, current.Parents...)
	}

	// Adding an edge dataset -> parent creates a cycle exactly when parent
	// can already reach the dataset by following parent edges in the
	// post-replacement graph.
	for _, parent := range wanted {
		if reachesAfterReplacement(graph, dataset.Name, wanted, parent, dataset.Name) {
			return fmt.Errorf("%w: dataset %q cannot depend on %q, it would reach itself", ErrCycle, dataset.Name, parent)
		}
	}

	// ---- All checks passed; commit below this line. ----

	current, existed := graph[dataset.Name]
	if !existed || current == nil {
		current = &Lineage{Dataset: dataset.Name}
		graph[dataset.Name] = current
	}

	newSet := toSet(wanted)
	for _, oldParent := range oldParents {
		if newSet[oldParent] {
			continue // relationship is kept
		}
		if entry := graph[oldParent]; entry != nil {
			entry.Children = removeName(entry.Children, dataset.Name)
		}
	}

	current.Parents = wanted
	for _, parent := range wanted {
		entry := graph[parent]
		entry.Children = addName(entry.Children, dataset.Name)
	}
	// Downstream is preserved; normalize defensively in case the map was
	// hand-edited before this call.
	current.Children = uniqueSorted(current.Children)

	return nil
}

// reachesAfterReplacement reports whether start can reach target by following
// parent edges. While walking, the parents of overrideNode are treated as
// overrideParents, which makes the traversal reflect the graph AS IT WILL BE
// after the pending registration rather than the graph being replaced.
func reachesAfterReplacement(graph map[string]*Lineage, overrideNode string, overrideParents []string, start, target string) bool {
	seen := map[string]bool{}
	var walk func(node string) bool
	walk = func(node string) bool {
		if node == target {
			return true
		}
		if seen[node] {
			return false
		}
		seen[node] = true

		var nextParents []string
		if node == overrideNode {
			nextParents = overrideParents
		} else if entry, ok := graph[node]; ok && entry != nil {
			nextParents = entry.Parents
		}
		for _, parent := range nextParents {
			if walk(parent) {
				return true
			}
		}
		return false
	}
	return walk(start)
}

// Roots lists datasets with no parents, sorted by name.
func Roots(graph map[string]*Lineage) []string {
	var roots []string
	for name, entry := range graph {
		if entry != nil && len(entry.Parents) == 0 {
			roots = append(roots, name)
		}
	}
	sort.Strings(roots)
	return roots
}

// uniqueSorted returns a sorted, duplicate-free copy of names. The result is
// nil when no name remains, so empty lineage stays empty.
func uniqueSorted(names []string) []string {
	if len(names) == 0 {
		return nil
	}
	seen := make(map[string]bool, len(names))
	out := make([]string, 0, len(names))
	for _, name := range names {
		if !seen[name] {
			seen[name] = true
			out = append(out, name)
		}
	}
	sort.Strings(out)
	return out
}

func toSet(names []string) map[string]bool {
	set := make(map[string]bool, len(names))
	for _, name := range names {
		set[name] = true
	}
	return set
}

// addName inserts name into the already-sorted list, skipping duplicates.
func addName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index < len(list) && list[index] == name {
		return list
	}
	list = append(list, "")
	copy(list[index+1:], list[index:])
	list[index] = name
	return list
}

// removeName drops name from the already-sorted list if it is present.
func removeName(list []string, name string) []string {
	index := sort.SearchStrings(list, name)
	if index >= len(list) || list[index] != name {
		return list
	}
	return append(list[:index], list[index+1:]...)
}

// Package chainledger applies the shared raw name-encoding rule (see
// name_encoding.go) to an adjustment plan.
//
// Every name that takes part in the lineage adjustment — the name of each
// change record, every upstreams entry, and every removals entry — is
// checked against its RAW string literal before the plan is accepted, even
// when a removals name would only have matched a dataset that does not
// exist. A literal carrying bytes that are not valid UTF-8, or a \u escape
// forming an unpaired surrogate (a lone high or low surrogate, or a low
// surrogate written before its high surrogate), rejects the whole plan.
//
// The change records reuse the same "name" + "upstreams" record checker as a
// graph's datasets, and field recognition, record reading, unknown-field
// skipping, locations, and the byte-vs-surrogate error wording are all the
// shared machinery in name_encoding.go and duplicate_fields.go, so the plan
// reader can never judge one name or record shape differently from the graph
// readers.
package chainledger

import (
	"encoding/json"
)

// checkPlanNameEncoding scans the raw plan JSON and rejects the whole plan
// when any name that participates in the adjustment — changes[i].name, any
// changes[i].upstreams[j], or any removals[i] — is written with a string
// literal the decoder cannot read faithfully (invalid UTF-8 bytes or an
// unpaired surrogate escape). The error names the field and the zero-based
// record or array position, and says which of the two corruptions occurred.
func checkPlanNameEncoding(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return scanObjectFields(dec, []knownField{
			{name: "changes", nested: func(dec *json.Decoder) error {
				return scanNameUpstreamsRecords(dec, "changes", "change record")
			}},
			{name: "removals", nested: scanRemovalsNames},
		})
	})
}

// Package chainledger guards every reader of lineage-bearing names against
// the same silent name substitution.
//
// encoding/json decodes every JSON string by replacing each invalid UTF-8
// byte — and each \u escape that is an unpaired surrogate — with U+FFFD, so
// the decoded document no longer names the datasets the file actually wrote.
// A corrupted reference can then collide with a real node: when one
// dataset's direct upstream is written as "源" plus one lone \uD800 escape,
// the decoder turns it into "源�" and the edge is silently accepted as a
// reference to the root dataset genuinely named "源�"; a corrupted removals
// entry could delete a dataset the user never named. The reader must not
// guess which dataset the file meant, so every name that takes part in
// lineage relations — each datasets[i].name and every
// datasets[i].upstreams[j] in a standalone graph file or in the graph
// embedded in a snapshot, and in a plan each changes[i].name, every
// changes[i].upstreams[j], and every removals[i] (even one that names a
// dataset that does not exist) — is checked against its RAW string literal
// before the document is accepted. A literal carrying bytes that are not
// valid UTF-8, or a \u escape forming an unpaired surrogate (a lone high or
// low surrogate, or a low surrogate written before its high surrogate),
// rejects the whole input: the decoder's rewrite is never kept, the
// offending node or edge is never skipped, and a snapshot whose declared
// content identifier happens to equal the rewritten graph's digest is still
// refused.
//
// Only the raw literal can tell corruption apart from a genuine name: the
// replacement character itself ("�", or the equivalent JSON escape) is legal
// and stays accepted, as is every correctly paired surrogate escape. Names
// that merely LOOK like escapes (a backslash followed by an ordinary letter,
// including a doubled backslash before "ud800") are plain text to JSON and
// are never rejected for that reason.
//
// This file is the single implementation of that rule, shared by the graph
// and plan document scopes in graph_name_encoding.go and
// plan_name_encoding.go. Field recognition is the reader's own — keys are
// compared after JSON unescaping with Unicode case folding via the shared
// walker in duplicate_fields.go (scanObjectFields/checkArrayElements) — so a
// field spelled "Name" is checked exactly like "name", unknown fields and
// everything nested inside them are skipped, and the graph and plan readers
// can never drift apart about which strings are names, how a record is read,
// or how an error is located. A document too malformed to walk is left to
// the regular parse, exactly as in duplicate_fields.go.
package chainledger

import (
	"encoding/json"
	"fmt"
	"unicode/utf8"
)

// graphNameFields is the field scope of one dataset record — the same shape
// whether the record sits in a graph's "datasets" array or in a plan's
// "changes" array — for the raw name-encoding scan: both its "name" string
// and every "upstreams" string element are lineage names and must each
// decode faithfully. Location wording is supplied per array field and
// record kind, so a dataset record and a change record judged at the same
// position fail with the same rule and only the document-specific nouns
// differ.
func graphNameFields(index int, arrayField, recordKind string) []knownField {
	return []knownField{
		{name: "name", nested: func(dec *json.Decoder) error {
			location := fmt.Sprintf("field %q in the %s at index %d of %q", "name", recordKind, index, arrayField)
			return checkNameStringEncoding(dec, location)
		}},
		{name: "upstreams", nested: func(dec *json.Decoder) error {
			return checkArrayElements(dec, func(dec *json.Decoder, item int) error {
				location := fmt.Sprintf("field %q at index %d in the %s at index %d of %q", "upstreams", item, recordKind, index, arrayField)
				return checkNameStringEncoding(dec, location)
			})
		}},
	}
}

// scanNameUpstreamsRecords validates every record of a "name" + "upstreams"
// array: datasets in a graph (arrayField "datasets", recordKind "dataset
// record") or changes in a plan ("changes", "change record"). The decoder
// must be positioned at the field's array value.
func scanNameUpstreamsRecords(dec *json.Decoder, arrayField, recordKind string) error {
	return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
		return scanObjectFields(dec, graphNameFields(index, arrayField, recordKind))
	})
}

// scanRemovalsNames validates every element of a plan's "removals" array.
// A removal is a lineage name even when the dataset it names does not
// exist, so its raw literal is checked like every other name. The decoder
// must be positioned at the field's array value.
func scanRemovalsNames(dec *json.Decoder) error {
	return checkArrayElements(dec, func(dec *json.Decoder, index int) error {
		location := fmt.Sprintf("field %q at index %d", "removals", index)
		return checkNameStringEncoding(dec, location)
	})
}

// checkNameStringEncoding consumes one value and, when it is a string
// literal, validates its raw bytes with validateNameStringLiteral. A
// non-string value is skipped: the regular parse reports the type error.
func checkNameStringEncoding(dec *json.Decoder, location string) error {
	var raw json.RawMessage
	if err := dec.Decode(&raw); err != nil {
		return errAbortScan
	}
	if len(raw) < 2 || raw[0] != '"' {
		return nil
	}
	return validateNameStringLiteral(raw, location)
}

// validateNameStringLiteral checks one raw JSON string literal (surrounding
// quotes included) for the two corruptions the decoder would silently
// rewrite to U+FFFD: bytes that are not valid UTF-8, and \u escapes forming
// an unpaired surrogate. The literal is known to be syntactically valid
// JSON (the regular parse already accepted the document), so escapes are
// well-formed; anything else unexpected aborts the scan and is left to that
// parse. location identifies the field and position in the error.
func validateNameStringLiteral(raw []byte, location string) error {
	end := len(raw) - 1 // index of the closing quote
	for i := 1; i < end; {
		c := raw[i]
		switch {
		case c == '\\':
			if i+1 >= end {
				return errAbortScan
			}
			if raw[i+1] != 'u' {
				i += 2 // \", \\, \/, \b, \f, \n, \r, \t
				continue
			}
			if i+6 > end {
				return errAbortScan
			}
			cp, ok := hex4(raw[i+2 : i+6])
			if !ok {
				return errAbortScan
			}
			i += 6
			switch {
			case isHighSurrogate(cp):
				// A high surrogate is legal only as the first half of a
				// pair: the very next escape must be its low surrogate.
				if i+6 <= end && raw[i] == '\\' && raw[i+1] == 'u' {
					if low, ok := hex4(raw[i+2 : i+6]); ok && isLowSurrogate(low) {
						i += 6
						continue
					}
				}
				return unpairedSurrogateError(location)
			case isLowSurrogate(cp):
				// A lone low surrogate — including one written before its
				// high surrogate — never forms a pair.
				return unpairedSurrogateError(location)
			}
		case c < utf8.RuneSelf:
			i++
		default:
			// A genuine U+FFFD decodes with size 3 and is accepted; only a
			// byte the decoder cannot map (size 1) is corruption.
			r, size := utf8.DecodeRune(raw[i:end])
			if r == utf8.RuneError && size == 1 {
				return invalidUTF8BytesError(location)
			}
			i += size
		}
	}
	return nil
}

// hex4 parses exactly four hexadecimal digits (one \u escape unit).
func hex4(b []byte) (rune, bool) {
	var v rune
	for _, c := range b {
		v <<= 4
		switch {
		case c >= '0' && c <= '9':
			v |= rune(c - '0')
		case c >= 'a' && c <= 'f':
			v |= rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v |= rune(c-'A') + 10
		default:
			return 0, false
		}
	}
	return v, true
}

func isHighSurrogate(cp rune) bool { return cp >= 0xD800 && cp <= 0xDBFF }
func isLowSurrogate(cp rune) bool  { return cp >= 0xDC00 && cp <= 0xDFFF }

// invalidUTF8BytesError reports a name whose raw string literal carries
// bytes that are not valid UTF-8.
func invalidUTF8BytesError(location string) error {
	return fmt.Errorf("%w: %s contains invalid UTF-8 bytes", ErrInvalidArgument, location)
}

// unpairedSurrogateError reports a name whose \u escapes form an unpaired
// surrogate (a lone high or low surrogate, or a low surrogate before its
// high surrogate).
func unpairedSurrogateError(location string) error {
	return fmt.Errorf("%w: %s contains an unpaired surrogate escape", ErrInvalidArgument, location)
}

// Package chainledger applies the shared raw name-encoding rule (see
// name_encoding.go) to a graph object, whether it stands alone as a graph
// file or is embedded as a snapshot's "graph" value.
//
// Every name a graph carries — each datasets[i].name and every
// datasets[i].upstreams[j] — is checked against its RAW string literal
// before the graph is accepted. A literal carrying bytes that are not valid
// UTF-8, or a \u escape forming an unpaired surrogate (a lone high or low
// surrogate, or a low surrogate written before its high surrogate), rejects
// the whole input: the decoder's U+FFFD rewrite is never kept, the offending
// node or edge is never skipped, and a snapshot whose declared content
// identifier happens to equal the rewritten graph's digest is still refused.
//
// Field recognition, record reading, unknown-field skipping, locations, and
// the byte-vs-surrogate error wording are the shared machinery in
// name_encoding.go and duplicate_fields.go, so a standalone graph file and
// an embedded snapshot graph are judged by exactly the same code.
package chainledger

import (
	"encoding/json"
)

// checkGraphNameEncoding scans the raw JSON of one graph object — either the
// whole of a standalone graph file or the "graph" value embedded in a
// snapshot — and rejects the entire document when any dataset name or direct
// upstream reference is written with a string literal the decoder cannot
// read faithfully (invalid UTF-8 bytes or an unpaired surrogate escape).
// The error names the field and the zero-based dataset record position, and
// for an upstream the zero-based array position too, and says which of the
// two corruptions occurred.
func checkGraphNameEncoding(data []byte) error {
	return runFieldScan(data, func(dec *json.Decoder) error {
		return scanObjectFields(dec, []knownField{
			{name: "datasets", nested: func(dec *json.Decoder) error {
				return scanNameUpstreamsRecords(dec, "datasets", "dataset record")
			}},
		})
	})
}

