116	// check on every element with its zero-based index. A value that is not an
117	// array is consumed and left for the regular parse to report.
118	func checkArrayElements(dec *json.Decoder, check func(dec *json.Decoder, index int) error) error {
119		tok, err := scanToken(dec)
