263					return err
264				}
265				if err := skipValue(dec); err != nil {
266					return err
267				}
268			}
269		case '[':
270			closer = ']'
271			for dec.More() {
272				if err := skipValue(dec); err != nil {
273					return err
274				}
275			}
276		default:
277			return errAbortScan
278		}
279		tok, err := scanToken(dec)
280		if err != nil {
281			return err
282		}
283		if end, ok := tok.(json.Delim); !ok || end != closer {
284			return errAbortScan
