		"real datasets then empty replacement": {
			`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[]}`,
			"datasets", "top level",
		},
		"null datasets then real": {
			`{"datasets":null,"datasets":[{"name":"A","upstreams":[]}]}`,
			"datasets", "top level",
