		},
		"case variant name": {
			`{"datasets":[{"Name":"A","name":"A","upstreams":[]}]}`,
			"name", `index 0 of "datasets"`,
		},
		"case variant datasets": {
			`{"Datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
			"datasets", "top level",
		},
