func TestParseSnapshotRejectsDuplicateFields(t *testing.T) {
	graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
	id := snapshotOf(t, graph).ContentID
	doc := func(body string) string {
