	// known field inside it.
	valid := doc(graph)

	cases := map[string]struct {
		data  string
		field string
	}{
		"version 2 then 1": {
			`{"formatVersion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
			"formatVersion",
		},
		"identical version twice": {
			`{"formatVersion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
			"formatVersion",
		},
		"contentId twice": {
